{
  "company": "CRONUS International Ltd.",
  "messageType": "Inventory.ItemCategory.Set",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "Inventory.ItemCategory.Set",
    "isEnabled": true,
    "filterTableNo": 5722,
    "description": "Stofnar eða uppfærir vöruflokk og sjálfgefna eiginleika hans.",
    "selectionDescription": "Stofnaðu eða breyttu vöruflokki og sjálfgefnum eiginleikum sem eru vistaðir á honum.",
    "messageDirection": "Inbound",
    "keywords": [
      "vöruflokkur",
      "yfirflokkur",
      "eiginleiki",
      "sjálfgefið gildi"
    ],
    "chargeable": true
  },
  "chapters": {
    "envelope": {
      "subject": {
        "use": "notUsed",
        "description": "The category is named under data.code or data.systemId; subject is not read."
      },
      "dataRequired": true,
      "version": "1.0",
      "contentType": "text/json"
    },
    "target": [
      {
        "source": "data.code",
        "form": "text",
        "description": "The item category to create or update, by code or by system id."
      },
      {
        "source": "data.systemId",
        "form": "guid",
        "description": "The system id of an existing item category, as an alternative to data.code. Send one of them, not both."
      }
    ],
    "parameters": [
      {
        "name": "code",
        "type": "string",
        "required": false,
        "description": "Category code, at most 20 characters. A new code creates the category; an existing code updates it. Send code or systemId, not both."
      },
      {
        "name": "systemId",
        "type": "string",
        "required": false,
        "description": "System id (GUID) of an existing category. Send code or systemId, not both."
      },
      {
        "name": "description",
        "type": "string",
        "required": false,
        "description": "Description of the category, at most 100 characters."
      },
      {
        "name": "parentCategory",
        "type": "string",
        "required": false,
        "description": "Parent category code. Used when the category is created. For an existing category it must equal the current parent; moving a category is refused."
      },
      {
        "name": "delete",
        "type": "boolean",
        "required": false,
        "description": "true or false. true is refused: this call does not delete categories."
      },
      {
        "name": "attributes",
        "type": "array",
        "required": false,
        "description": "Array of attribute defaults to store on this category. Each entry is an object with name (text) or id (number) of an existing attribute, and value (text) naming an existing value of that attribute. Dates are yyyy-mm-dd and decimals use a period.",
        "children": [
          {
            "name": "name",
            "type": "string",
            "required": false,
            "description": "Name of an existing attribute. Send name or id, not both."
          },
          {
            "name": "id",
            "type": "integer",
            "required": false,
            "description": "ID of an existing attribute. Send name or id, not both."
          },
          {
            "name": "value",
            "type": "string",
            "required": true,
            "description": "An existing value of that attribute, as text. Dates are yyyy-mm-dd and decimals use a period."
          }
        ]
      }
    ],
    "response": {
      "contentType": "text/json",
      "fields": [
        {
          "name": "status",
          "type": "string",
          "description": "Success on a successful call; Error responses use the standard error envelope."
        },
        {
          "name": "created",
          "type": "boolean",
          "description": "True when the call created the category, false when it updated an existing one."
        },
        {
          "name": "code",
          "type": "string",
          "description": "The category code."
        },
        {
          "name": "description",
          "type": "string",
          "description": "The category description after the save."
        },
        {
          "name": "parentCategory",
          "type": "string",
          "description": "The code of the parent category; empty at the top of the tree."
        },
        {
          "name": "indentation",
          "type": "integer",
          "description": "The indentation level in the category tree."
        },
        {
          "name": "presentationOrder",
          "type": "integer",
          "description": "The position of the category in the tree."
        },
        {
          "name": "attributes",
          "type": "array",
          "description": "Every attribute of the saved category, own values first and then values inherited from parent categories, not only the ones in the request.",
          "children": [
            {
              "name": "id",
              "type": "integer",
              "description": "The ID of the item attribute."
            },
            {
              "name": "name",
              "type": "string",
              "description": "The name of the item attribute."
            },
            {
              "name": "type",
              "type": "string",
              "description": "The type of the attribute: Option, Text, Integer, Decimal or Date."
            },
            {
              "name": "value",
              "type": "string",
              "description": "The default value of the attribute for the category."
            },
            {
              "name": "inherited",
              "type": "boolean",
              "description": "True when the value comes from a parent category; false when it is set on the category itself."
            }
          ]
        }
      ]
    },
    "errors": [
      {
        "code": "MissingParameter",
        "when": "code or systemId is missing or empty, or an attributes entry has no name or id, or no value.",
        "fix": "Send code or systemId, and name or id plus value on each attributes entry."
      },
      {
        "code": "InvalidParameterFormat",
        "when": "A key has the wrong JSON type, or systemId is not a GUID.",
        "fix": "Send code, systemId, description, parentCategory, name and value as text, id as a number, delete as true or false, and attributes as an array of objects."
      },
      {
        "code": "UnknownParameter",
        "when": "The request or an attributes entry contains a key this type does not read.",
        "fix": "Remove the unknown key. Allowed keys are code, systemId, description, parentCategory, delete and attributes; each attributes entry allows name, id and value."
      },
      {
        "code": "RecordNotFound",
        "when": "The attribute or attribute value does not exist, or no category matched systemId or parentCategory.",
        "fix": "Create the attribute with Inventory.AttributeDefinition.Create first."
      },
      {
        "code": "ConflictingIdentifiers",
        "when": "code and systemId, or name and id on one attributes entry, were both sent.",
        "fix": "Send code or systemId, and name or id, not both."
      },
      {
        "code": "InvalidParameter",
        "when": "parentCategory would put the category inside its own subtree.",
        "fix": "Choose a parent outside this category's subtree."
      },
      {
        "code": "InvalidParameter",
        "when": "A text is longer than its field, or the Item Category domain is turned off.",
        "fix": "Send a code of at most 20 characters and a description of at most 100, or turn the domain on from the Inventory Setup page."
      },
      {
        "code": "PreconditionFailed",
        "when": "The call asks to delete a category or to move an existing category under another parent.",
        "fix": "Use the Item Categories page to delete or reparent a category."
      },
      {
        "code": "PreconditionFailed",
        "when": "The attribute or the attribute value is blocked.",
        "fix": "Choose an attribute and a value that are not blocked."
      },
      {
        "code": "PermissionDenied",
        "when": "The caller cannot change item categories or their attributes.",
        "fix": "Assign Bifrost Full Access with Inventory write permissions and a Business Central permission set that can change these tables."
      },
      {
        "code": "BusinessCentralError",
        "when": "Business Central refuses the save itself, after the request was checked. Nothing is saved.",
        "fix": "Read the error text, correct the cause in Business Central and send the call again."
      }
    ],
    "effect": {
      "effect": "write",
      "writes": true,
      "posts": false,
      "changes": "Creates the item category, or changes the description of an existing one, and stores the listed attribute defaults on it. A value equal to the one inherited from a parent category removes the own row of the category for that attribute. Categories are never deleted or moved. A refusal saves nothing. Chained Omit Commit calls stay in the caller transaction; standalone calls use an isolated write.",
      "idempotent": true,
      "permissionSet": "Bifrost Full Access",
      "preconditions": [
        "Every attribute and attribute value named in attributes already exists and is not blocked.",
        "A parent category named in parentCategory exists, and an existing category keeps the parent it has."
      ]
    },
    "metering": {
      "chargeable": true,
      "chargedAs": "message"
    },
    "related": [
      {
        "name": "Inventory.ItemCategory.Get",
        "useInsteadWhen": "Read the category tree and the inherited attributes instead of changing them."
      },
      {
        "name": "Inventory.AttributeDefinition.Create",
        "useInsteadWhen": "Create the attribute and its values first when they do not exist yet."
      }
    ],
    "workflow": {
      "steps": [
        {
          "messageType": "Inventory.AttributeDefinition.Create",
          "purpose": "Create the attribute and its values when they do not exist yet."
        },
        {
          "messageType": "Inventory.ItemCategory.Set",
          "purpose": "Create the category or change its description and its attribute defaults."
        },
        {
          "messageType": "Inventory.ItemCategory.Get",
          "purpose": "Read the category back, with the attributes it inherits from its parents."
        }
      ]
    },
    "examples": [
      {
        "title": "Create a child category with a default color",
        "request": {
          "type": "Inventory.ItemCategory.Set",
          "data": {
            "code": "CHAIRS",
            "description": "Chairs",
            "parentCategory": "FURNITURE",
            "attributes": [
              {
                "name": "Color",
                "value": "Blue"
              }
            ]
          }
        },
        "response": {
          "status": "Success",
          "created": true,
          "code": "CHAIRS",
          "description": "Chairs",
          "parentCategory": "FURNITURE",
          "indentation": 1,
          "presentationOrder": 2,
          "attributes": [
            {
              "id": 1,
              "name": "Color",
              "type": "Option",
              "value": "Blue",
              "inherited": false
            }
          ]
        }
      }
    ],
    "overview": "Creates an item category, or updates the description of an existing one, and stores attribute defaults on that category. Each attribute and value must already exist. A value equal to the value inherited from a parent category is not stored on the category itself, and the answer lists it with inherited true. The answer is the saved category with created, its tree position and its attributes.",
    "notes": "A successful call saves the category and its attribute defaults. A refusal leaves every category and attribute unchanged. The call does not delete categories, does not move an existing category to another parent and does not post. Items already in the category keep their own attribute values; the defaults apply to items assigned to the category later. Generic data writes to item categories and their attribute rows are refused, so use this call. In a chained Omit Commit call, the write remains in the caller transaction and a native failure propagates so the whole chain can roll back."
  },
  "conventions": "## Errors and warnings\r\nAn error response has `status` = `Error`, a stable `code`, the `error` text and, when they apply, `parameter` (the request parameter concerned, e.g. `lines[2].no`), `received` (the value received), `expected` (what was expected) and `nextStep` (what to do now). `hint` says where to read more.\r\nWhen a request has several problems, all of them are listed in `errors[]` - each with the same fields - under a top-level `code` (`MultipleErrors`, or a shared code such as `InvalidLine` for the `lines` of a Create type) and a summary `error`. Fix them all before calling again. One problem is reported at the top level, with no `errors[]`.\r\nRequest values are checked first and every problem found is reported together. A Business Central validation error raised afterwards, while a record is being written, stops the call and is reported on its own: `code` = `BusinessCentralError`, Business Central's own `error` text, and `parameter` naming the request parameter being applied, e.g. `lines[1].accountNo`. Nothing is written.\r\nRequest values are read in one format, whatever the language: dates `YYYY-MM-DD`; date-times ISO 8601 with `Z` or an offset; amounts as JSON numbers (or a string such as `\"1234.56\"`, no thousands separator); integers as JSON integers; booleans `true` or `false`. Any other value is `InvalidParameterFormat` with `received` and `expected`; for an unambiguous local form such as `26.09.2026`, `nextStep` gives the value to resend. Every bad value of a request is reported together.\r\nAnswers are written in one format as well, whatever the language of the call: dates `YYYY-MM-DD`, date-times ISO 8601, numbers with a dot and no thousands separator, and the option and enum values of every answer except `Data.Records.Get` and `Data.Records.Set` as their English names, so a value read from an answer can be sent back. Those two answer the caption of the language of the call, for a person to read. The language of the call (`lcid`) changes captions and message texts, not these forms. Two things are outside Bifrost's control: Business Central writes its own texts (a ledger entry description such as `Direct Cost V00010 on 10/02/26`, the text of a `BusinessCentralError`) with the regional settings of the server session, which `lcid` does not change, so a date in such a text can be in month-day order; and a table view is read with those settings too, so write dates in a view as `YYYY-MM-DD` and decimals with a dot.\r\nBoth success and error responses can carry `warnings[]`, each with `code`, `message` and, when they apply, `parameter` and `nextStep`.\r\n`UnknownParameter` refuses undeclared data keys before execution for every type whose effect is not read, including a missing effect. The root envelope option `strict:false` cannot opt out. Read types keep warnings without changing status, validationResult or domain warningCount unless the caller sets `strict:true` (next to type and subject, never inside data). Refusals list the keys and localized nextStep corrections; no business changes or successful execution charges occur. Example: {\"type\":\"Memory.User.Set\",\"strict\":true,\"data\":{\"memory\":\"test\",\"memry\":\"typo\"}} is refused.\r\n`FieldChangedByBC` is a warning from Data.Records.Set: another field validation or the write changed a sent field after its own validation. `parameter` names data[n].fields.{jsonName}, counting from 0. Status stays Success. Compare the returned values with what you sent; follow `nextStep` to use validation order or send the field again in a separate call. Normalisation of the field itself, LCY, Dimension Set ID, BLOB, Media, MediaSet and skipped fields are excluded.\r\nViðbætur (Foundation 28.0.8 eða nýrri) geta kallað á `Argument.SetErrorContext(Parameter, Expected, NextStep)` fyrir aðgerð sem gæti mistekist eftir gagnaskrif og síðan `Argument.ClearErrorContext()` eftir að hún tekst. Gefðu upp heiti færibreytu og þýddan texta, aldrei gildi úr beiðni, skráarinnihald, aðgangsupplýsingar eða kallstafla. Foundation skilar þessu samhengi með upprunalegu `BusinessCentralError` eftir afturköllun, einnig við ómeðhöndlaðar verkefnisvillur; `RespondWithLastError()` notar það líka. Viðmótið grípur ekki villur, staðfestir ekki gagnaskrif og breytir ekki færslumörkum. Haltu `Codeunit.Run` án skilagildis og láttu villur berast áfram þegar `OmitCommit` köll eru keðjuð; bættu aldrei við Boolean `Codeunit.Run` eða `TryFunction` sem skrifar gögn til að endurheimta samhengi. Samhengið er hreinsað milli skilaboða. Kallendur án samhengis halda óbreyttri uppbyggingu svars; þekktar læsingarvillur halda núverandi `Retryable` leiðbeiningum.\r\nSkilaboðagerð sem má aðeins keyra eftir einni leið (Foundation 28.0.9 eða nýrri) les `Argument.GetInvocationSource()`: `Queue` þegar verkraðari keyrir skilaboð sem biðraðarviðmótið setti í röð, `Task` fyrir verkviðmótið (`/tasks`), `Dispatcher` fyrir innra kall í gegnum `Dispatcher ori` (innbyggða MCP-verkfæraþjóninn, hreiðrað kall úr annarri skilaboðagerð) og `Direct` fyrir aðgerðina Keyra vinnslu á síðunni Skilaboð og allt sem ekki er skráð. Aðeins Foundation skráir gildið; gildi í beiðni, færibreytur, uppruni, efni og skrif í færibreytuna breyta því ekki. Hafnaðu öðrum leiðum með `PreconditionFailed` og `nextStep` sem nefnir leiðina sem á að nota.\r\n`Retryable` means a transient lock or deadlock caught while writing or posting. `error` keeps Business Central's original text. `expected` is \"no concurrent lock on the same records\"; `nextStep` is \"Retry the same call after a few seconds; nothing was changed.\" Bifrost does not retry automatically. Other platform errors, including uncaught queue-path errors, remain `BusinessCentralError`.\r\nCodes: `MissingParameter`, `InvalidParameterFormat`, `InvalidParameter`, `RecordNotFound`, `AmbiguousRecord`, `ConflictingIdentifiers`, `InvalidFilterField`, `InvalidLine`, `NothingToPreview`, `LinesSkipped`, `BlockedByWriteGuard`, `PreconditionFailed`, `PermissionDenied`, `LimitExceeded`, `BusinessCentralError`, `MultipleErrors`, `DeprecatedParameter`, `UnknownParameter`, `FieldChangedByBC`, `Retryable`, `EULA_REQUIRED`, `TRIAL_NOT_STARTED`. The `error` text may be translated; the code never is.\r\n"
}
